INSERT INTO public.legal_documents (document_code, title, audience, scope, language, version, status, content, summary, requires_acceptance)
VALUES
('saas_subscription_contract', 'Contrat d''abonnement SaaS BPEI', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider juridiquement avant utilisation.\n\n1. Parties\nÉditeur : {{BPEI_LEGAL_NAME}}, {{BPEI_LEGAL_FORM}} au capital de {{BPEI_CAPITAL}}, dont le siège est situé {{BPEI_ADDRESS}}, immatriculée sous le SIREN {{BPEI_SIREN}}.\nClient : {{PROFESSIONAL_NAME}}, SIREN {{PROFESSIONAL_SIREN}}.\n\n2. Objet\nLe présent contrat a pour objet la fourniture d''un accès au logiciel BPEI selon le plan {{PLAN_NAME}} ({{PLAN_PRICE}}) souscrit par le Client. Les fonctionnalités précises figurent en Annexe fonctionnelle.\n\n3. Durée et prise d''effet\nLe contrat prend effet à la date {{CONTRACT_START_DATE}} pour une durée initiale de {{CONTRACT_INITIAL_TERM_MONTHS}} mois, renouvelable par tacite reconduction sauf dénonciation dans les conditions prévues à l''article 8.\n\n4. Prix et facturation\nLe prix mensuel est de {{PLAN_PRICE}} HT. Les modalités de facturation figurent dans l''Annexe abonnement.\n\n5. Obligations de l''Éditeur\nL''Éditeur met à disposition le service dans des conditions raisonnables de disponibilité, sans garantie chiffrée hors annexe SLA à valider ultérieurement.\n\n6. Obligations du Client\nLe Client s''engage à un usage conforme aux règles décrites dans la charte du réseau et à la protection de ses identifiants.\n\n7. Données personnelles\nLes traitements réalisés pour le compte du Client relèvent de l''Accord de sous-traitance RGPD annexé.\n\n8. Résiliation\nChaque partie peut résilier selon les modalités précisées dans la politique de suspension et résiliation.\n\n9. Réversibilité\nLes conditions d''export et de restitution des données figurent dans l''Annexe réversibilité.\n\n10. Loi applicable et juridiction\nLe droit français s''applique. En cas de litige, les parties tenteront un règlement amiable ({{MEDIATOR_NAME}}) avant toute action judiciaire devant le tribunal compétent.\n',
'Contrat maître SaaS renvoyant à ses annexes.', false),

('subscription_annex', 'Annexe d''abonnement', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider juridiquement.\n\n1. Plan souscrit : {{PLAN_NAME}}\n2. Prix mensuel HT : {{PLAN_PRICE}}\n3. Périodicité de facturation : {{BILLING_CYCLE}}\n4. Mode de paiement autorisé : {{PAYMENT_METHODS}}\n5. Date de début : {{CONTRACT_START_DATE}}\n6. Modalités de révision tarifaire : à préciser par avenant.\n7. Utilisateurs inclus : {{PLAN_USERS_LIMIT}}\n8. Établissements inclus : {{PLAN_LOCATIONS_LIMIT}}\n',
'Annexe financière du contrat SaaS.', false),

('functional_annex', 'Annexe fonctionnelle', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider.\n\nDescriptif détaillé des fonctionnalités couvertes par le plan {{PLAN_NAME}}. Les modules non listés dans cette annexe sont exclus du périmètre contractuel, en particulier les modules dont le statut est encore « blocked », « architecture_only » ou « legal_review_pending » dans le registre des modules sensibles.\n\nModules couverts : {{PLAN_MODULES}}\nLimites principales : {{PLAN_LIMITS}}\nModules exclus ou en préparation : à préciser.\n',
'Périmètre fonctionnel du plan.', false),

('security_annex', 'Annexe sécurité', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider.\n\n1. Hébergement des données : {{HOSTING_PROVIDER}} — {{HOSTING_LOCATION}}\n2. Sauvegardes : fréquence et rétention à préciser.\n3. Chiffrement au repos et en transit : à préciser.\n4. Journalisation des accès sensibles.\n5. Procédure d''incident : voir document dédié.\n6. Points de contact : {{SUPPORT_EMAIL}}, DPO {{DPO_EMAIL}}.\n7. Engagements de disponibilité : aucun SLA chiffré n''est garanti tant qu''il n''a pas été validé et signé.\n',
'Engagements de sécurité — non conformes tant que non validés.', false),

('reversibility_annex', 'Annexe réversibilité', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider.\n\n1. Format d''export : CSV / JSON structuré pour les données métier (clients, réparations, factures, stocks, commandes).\n2. Délai maximal d''export après demande : {{EXPORT_DELAY_DAYS}} jours ouvrés.\n3. Modalités de restitution : mise à disposition d''un lien sécurisé via {{SUPPORT_EMAIL}}.\n4. Durée de conservation des exports : {{EXPORT_RETENTION_DAYS}} jours.\n5. Assistance à la migration : sur devis.\n6. Suppression définitive : après confirmation écrite du Client et respect des durées légales de conservation.\n',
'Modalités de restitution et migration.', false),

('dpa', 'Accord de sous-traitance RGPD', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider par un DPO.\n\n1. Objet\n{{BPEI_LEGAL_NAME}} agit en qualité de sous-traitant au sens de l''article 28 du RGPD pour les traitements effectués pour le compte du Client dans le cadre du service SaaS BPEI.\n\n2. Description des traitements\nVoir cartographie RGPD interne — la liste précise doit être arrêtée après validation.\n\n3. Sous-traitants ultérieurs\n{{SUBPROCESSORS}} — la liste doit être maintenue à jour dans la console patron.\n\n4. Localisation des données : {{HOSTING_LOCATION}}\n5. Durées de conservation : voir politique de conservation propre à chaque catégorie.\n6. Mesures de sécurité : voir annexe sécurité.\n7. Assistance en cas de violation de données : notification sous {{BREACH_NOTIFICATION_HOURS}} heures.\n8. Droits des personnes : le Client reste responsable de traitement et gère les demandes d''accès, rectification, effacement, portabilité, opposition et limitation.\n9. Sort des données en fin de contrat : voir annexe réversibilité.\n',
'DPA article 28 — modèle à faire valider par un DPO.', true),

('network_charter', 'Charte du réseau BPEI', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider.\n\n1. Esprit du réseau : coopération professionnelle, entraide, refus de la concurrence déloyale.\n2. Engagements du membre : information sincère du client, respect des tarifs affichés, transparence sur les délais, respect du secret professionnel.\n3. Modération : {{BPEI_LEGAL_NAME}} peut suspendre un membre en cas de manquement grave selon la politique de suspension.\n4. Communication : le membre s''engage à ne pas se prévaloir d''une accréditation ou certification qui ne lui aurait pas été délivrée.\n5. Marque BPEI : usage encadré par la licence d''utilisation de la marque.\n',
'Règles de vie du réseau BPEI.', true),

('brand_license', 'Licence d''utilisation de la marque BPEI', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider par un conseil en propriété industrielle.\n\n1. Concédant : {{BPEI_LEGAL_NAME}}, titulaire de la marque BPEI (dépôt à confirmer).\n2. Licencié : {{PROFESSIONAL_NAME}}.\n3. Étendue : usage non exclusif, non transférable, limité au territoire français, pour la seule communication de l''appartenance au réseau BPEI.\n4. Charte graphique : usage conforme au kit de marque fourni.\n5. Contrôle qualité : {{BPEI_LEGAL_NAME}} peut demander la cessation immédiate d''un usage non conforme.\n6. Durée : liée au contrat SaaS en cours.\n7. Résiliation : cessation immédiate en cas de radiation du réseau.\n',
'Licence d''usage de la marque BPEI par les membres.', true),

('shop_independent_framework', 'Contrat-cadre boutique / indépendant', 'professional', 'partner', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider (risque de requalification en contrat de travail à évaluer).\n\n1. Parties : {{SHOP_LEGAL_NAME}} et {{INDEPENDENT_LEGAL_NAME}}.\n2. Objet : cadre d''intervention ponctuelle d''un professionnel indépendant pour le compte de la boutique.\n3. Nature de la relation : prestation de service entre professionnels indépendants — absence de lien de subordination.\n4. Bons de mission : chaque intervention fait l''objet d''un bon de mission signé (voir modèle).\n5. Facturation : chaque intervention est facturée directement par l''indépendant à la boutique ou au client final selon la mission.\n6. Assurances : chaque partie déclare disposer d''une RC pro adaptée — références {{SHOP_INSURANCE_REF}} / {{INDEPENDENT_INSURANCE_REF}}.\n7. Confidentialité : engagement mutuel de discrétion sur les données clients transmises.\n8. Durée et résiliation : contrat-cadre non exclusif, résiliable par chaque partie avec un préavis de {{FRAMEWORK_NOTICE_DAYS}} jours.\n',
'Cadre juridique des interventions boutique/indépendant.', false),

('mission_order_template', 'Modèle de bon de mission', 'professional', 'partner', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL — à compléter et faire valider.\n\n1. Référence : {{MISSION_REFERENCE}}\n2. Boutique donneuse d''ordre : {{SHOP_LEGAL_NAME}}\n3. Intervenant : {{INDEPENDENT_LEGAL_NAME}}\n4. Client final : {{CUSTOMER_NAME}} — coordonnées transmises pour la seule mission.\n5. Nature de l''intervention : {{MISSION_SCOPE}}\n6. Lieu : {{MISSION_LOCATION}}\n7. Date : {{MISSION_DATE}}\n8. Prix convenu : {{MISSION_PRICE}}\n9. Qui facture le client final : {{INVOICING_PARTY}}\n10. Qui répond au client en cas de réclamation : {{SUPPORT_PARTY}}\n11. Signatures : boutique et intervenant.\n',
'Bon de mission par intervention — cadre le rôle de chaque partie.', false),

('incident_procedure', 'Procédure d''incident de sécurité', 'internal', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL / OPÉRATIONNEL — à compléter et faire valider.\n\n1. Détection : tout collaborateur ou utilisateur peut signaler un incident via {{SECURITY_CONTACT_EMAIL}}.\n2. Qualification : classification sous 24 h ouvrées (bas, moyen, élevé, critique).\n3. Confinement et remédiation : mesures immédiates, journal horodaté.\n4. Notification interne : owner_bpei et responsable sécurité.\n5. Notification aux personnes concernées et à l''autorité de contrôle : selon obligations légales, dans les délais requis lorsque l''évaluation confirme la nécessité.\n6. Retour d''expérience : rapport post-incident et actions correctives documentées dans le registre des incidents.\n',
'Procédure interne — non conforme tant qu''elle n''a pas été validée.', false),

('data_export_deletion_procedure', 'Procédure d''export et de suppression des données', 'professional', 'platform', 'fr', 1, 'draft',
E'BROUILLON CONTRACTUEL / OPÉRATIONNEL — à compléter et faire valider.\n\n1. Demande : formulée par le client via {{SUPPORT_EMAIL}} ou depuis /demande-donnees.\n2. Vérification d''identité : documentée avant tout traitement.\n3. Délai de traitement : au maximum {{PRIVACY_REQUEST_DELAY_DAYS}} jours calendaires.\n4. Format d''export : voir annexe réversibilité.\n5. Suppression : effective sous {{DELETION_DELAY_DAYS}} jours après confirmation, sous réserve des durées légales de conservation (facturation, comptabilité, obligations fiscales).\n6. Journalisation : chaque demande fait l''objet d''une entrée dans le registre des demandes RGPD.\n',
'Procédure d''export / suppression — modèle à faire valider.', true)

ON CONFLICT (document_code, version, language, scope) DO NOTHING;